<script setup>
import { useViewRoute } from './useViewRoute'
import {ref,computed,toRaw,defineAsyncComponent} from 'vue'
import PagedRows from './components/PagedRows.vue'
import RelayTable from './components/RelayTable.vue'
import DocumentForm from './components/DocumentForm.vue'
import {arrayPageSource,fuzzyMatch} from './components/search'
import ConversationTimeline from './components/ConversationTimeline.vue'
const ConnectedMessages=defineAsyncComponent(()=>import('./components/ConnectedMessages.vue'))
const AutomationWorkspace=defineAsyncComponent(()=>import('./components/AutomationWorkspace.vue'))
const WhatsAppWorkspace=defineAsyncComponent(()=>import('./components/WhatsAppWorkspace.vue'))
const WorkspaceView=defineAsyncComponent(()=>import('./components/WorkspaceView.vue'))
import {Button,FormControl,Badge,Avatar,FeatherIcon,ErrorMessage} from '@relay/ui'
import {threadData,teamData,flowData,contactData} from './data'
const workspaceItems=ref([])
let draftSequence=1
const creating=ref(false), newContact=ref(''),newChannel=ref('WhatsApp')
function createConversation(){const c=contactData.find(c=>c.id===newContact.value);if(!c||!c.channels.includes(newChannel.value))return;let t=threads.value.find(t=>t.contact===c.id);if(!t){t={id:'RELAY-DRAFT-'+String(draftSequence++).padStart(6,'0'),contact:c.id,name:c.name,channel:newChannel.value,team:'Support',assignee:'You',status:'Open',bot:false,unread:0,messages:[]};threads.value.push(t)}openChat(t.id);replyChannel.value=newChannel.value;creating.value=false}
const channelFilter=ref('All'), replyChannel=ref(''), channelSettings=ref(''), expandedChannel=ref('')
const availableChannels=computed(()=>contactData.find(c=>c.id===current.value.contact)?.channels||[current.value.channel])
const conversationMessages=computed(()=>threads.value.filter(t=>current.value.contact?t.contact===current.value.contact:t.id===active.value).flatMap(t=>t.messages.map(m=>({...m,channel:m.channel||t.channel}))).filter(m=>channelFilter.value==='All'||m.channel===channelFilter.value))
const folderForm=ref(false)
const folderName=ref(''), folderError=ref(''), folders=ref([{id:'follow-up',name:'Follow up',threads:['c1']}]), selectedFolder=ref('')
const mobileNav=ref(false)
const mobileChat=ref(false), showDetails=ref(false)
const view=useViewRoute(['Dashboard','Inbox','Contacts','Campaigns','Canned replies','Flows','Teams','Channels','WhatsApp','Messages','Automation'],'Inbox'),threads=ref(structuredClone(threadData)),teams=ref(structuredClone(teamData)),nodes=ref(structuredClone(flowData)),active=ref('c1'),draft=ref(''),search=ref(''),filter=ref('All'),note=ref(false),team=ref(null),original=ref(''),error=ref(''),saved=ref(''),selected=ref(1),flowOpen=ref(false),published=ref(false)
const current=computed(()=>threads.value.find(t=>t.id===active.value)),rows=computed(()=>threads.value.filter(t=>fuzzyMatch(t.name+' '+t.team,search.value)&&(filter.value!=='Unassigned'||t.assignee==='Unassigned')&&(filter.value!=='Uncategorized'||!t.contact)&&(filter.value!=='Unread'||t.unread>0)&&(filter.value!=='Important'||t.important)&&(!selectedFolder.value||folders.value.find(f=>f.id===selectedFolder.value)?.threads.includes(t.id)))),node=computed(()=>nodes.value.find(n=>n.id===selected.value))
const conversationSource=arrayPageSource(()=>rows.value,t=>t.name+' '+t.team)
const teamSearch=ref(''),flowSearch=ref('')
const teamSource=arrayPageSource(()=>teams.value.map(t=>({...t,id:t.name})),t=>t.name+' '+t.channels.join(' '))
const flowSource=arrayPageSource(()=>[{id:'order-status',name:'Order status',channels:['WhatsApp','Telegram'],trigger:'/order',status:published.value?'Published':'Draft'}])
const newConversation=computed({get:()=>({contact:newContact.value,channel:newChannel.value}),set:v=>{newContact.value=v.contact;newChannel.value=v.channel}})
const conversationFields=computed(()=>[{name:'contact',label:'Contact',type:'Link',options:contactData.map(c=>({label:c.name,value:c.id})),required:true},{name:'channel',label:'Channel',type:'Select',options:contactData.find(c=>c.id===newContact.value)?.channels||[],required:true}])
function nav(v){mobileNav.value=false;view.value=v;error.value='';saved.value='';selectedFolder.value='';filter.value='All'}
function openChat(id){if(!id)return;view.value='Inbox';active.value=id;channelFilter.value='All';replyChannel.value='';draft.value='';mobileChat.value=true;threads.value.filter(t=>current.value.contact?t.contact===current.value.contact:t.id===id).forEach(t=>t.unread=0)}
function setFilter(f){nav('Inbox');filter.value=f}
function addFolder(){folderError.value='';const name=folderName.value.trim();if(!name){folderError.value='Enter a folder name.';return}if(folders.value.some(f=>f.name.toLowerCase()===name.toLowerCase())){folderError.value='Folder already exists.';return}folders.value.push({id:'RELAY-FOLDER-'+String(draftSequence++).padStart(6,'0'),name,threads:[]});folderName.value='';folderForm.value=false}
function toggleFolder(id){const f=folders.value.find(f=>f.id===id);f.threads=f.threads.includes(active.value)?f.threads.filter(x=>x!==active.value):[...f.threads,active.value]}
function folderUnread(f){return threads.value.filter(t=>f.threads.includes(t.id)&&t.unread>0).length}

function edit(t){team.value=structuredClone(toRaw(t));original.value=t.name;error.value='';saved.value=''}
function save(){error.value='';if(!team.value.name.trim())return error.value='Team name is required.';if(!team.value.members.some(m=>m.role==='Manager'))return error.value='Add at least one manager.';if(!team.value.channels.length)return error.value='Select at least one channel.';if(teams.value.some(t=>t.name===team.value.name&&t.name!==original.value))return error.value='Team name already exists.';const i=teams.value.findIndex(t=>t.name===original.value);if(i<0)teams.value.push(structuredClone(toRaw(team.value)));else teams.value[i]=structuredClone(toRaw(team.value));threads.value.filter(t=>t.team===original.value).forEach(t=>t.team=team.value.name);original.value=team.value.name;saved.value='Saved'}
function send(){if(!draft.value.trim())return;current.value.messages.push({who:note.value?'You · Note':'You',text:draft.value,time:'Now',channel:replyChannel.value||current.value.channel,out:true,note:note.value});draft.value=''}
function saveFlow(p){error.value='';if(nodes.value.some(n=>!n.value.trim()))return error.value='Complete all node fields.';if(!nodes.value[0].value.startsWith('/'))return error.value='Command must start with /.';published.value=p;saved.value=p?'Published':'Draft saved'}
threads.value[0].unread=0
</script>
<template><div class="app-shell"><aside class="app-nav" :class="{'mobile-nav-open':mobileNav}" @keydown.esc="mobileNav=false"><div class="flex items-center gap-2 px-2 py-5 mb-4"><button aria-label="Toggle navigation" :aria-expanded="mobileNav" @click="mobileNav=!mobileNav"><FeatherIcon name="message-circle" class="h-6 w-6"/></button><strong class="nav-label">Relay Core</strong></div><button v-for="[v,icon] in [['Dashboard','grid'],['Inbox','inbox'],['Contacts','users'],['Campaigns','send'],['Canned replies','message-square'],['Flows','git-branch'],['Teams','user-check'],['Channels','radio'],['WhatsApp','phone'],['Messages','message-circle'],['Automation','zap']]" :key="v" class="nav-item" :aria-label="v" :class="{active:view===v}" @click="nav(v)"><FeatherIcon :name="icon" class="h-4 w-4"/><span class="nav-label">{{v}}</span></button><section class="nav-label mt-6 px-2 space-y-2 min-h-0 overflow-auto"><div class="text-xs text-ink-gray-5 mb-3">PERSONAL</div><button class="nav-item" @click="setFilter('Important')">Important <span class="ml-auto">{{threads.filter(t=>t.important).length}}</span></button><button v-for="f in folders" :key="f.id" class="nav-item" :class="{active:selectedFolder===f.id}" @click="nav('Inbox');selectedFolder=f.id">{{f.name}}<span class="ml-auto">{{folderUnread(f)}}</span></button><Button v-if="!folderForm" label="New folder" icon-left="plus" variant="ghost" @click="folderForm=true"/><FormControl v-if="folderForm" v-model="folderName" placeholder="New folder" aria-label="New folder"/><Button v-if="folderForm" label="Add folder" variant="ghost" @click="addFolder"/><ErrorMessage :message="folderError"/></section><div class="mt-auto flex items-center gap-2 p-2 border-t"><Avatar label="Sakthi"/><span class="nav-label text-sm">Sakthi</span></div></aside><main class="workspace"><header class="page-header"><strong class="text-base">{{view}}<span v-if="view==='Flows'&&flowOpen" class="text-ink-gray-4"> / Order status</span></strong><Badge v-if="view!=='Messages'" label="Preview"/><div class="ml-auto flex items-center gap-2"><span role="status" class="text-sm text-ink-gray-5">{{saved}}</span><template v-if="view==='Teams'"><Button v-if="team" label="Save" variant="solid" @click="save"/><Button v-else label="New team" variant="solid" icon-left="plus" @click="edit({name:'',members:[{name:'Sakthi',role:'Manager'}],channels:[]})"/></template><template v-if="view==='Flows'&&flowOpen"><Badge :label="published?'Published':'Draft'"/><Button label="Save draft" @click="saveFlow(false)"/><Button label="Publish" variant="solid" @click="saveFlow(true)"/></template></div></header>
<template v-if="view==='Inbox'"><div class="toolbar inbox-toolbar"><Button v-for="f in ['All','Unread','Unassigned','Uncategorized']" :key="f" :label="f" :variant="filter===f?'subtle':'ghost'" @click="filter=f"/><Button label="New conversation" icon-left="plus" @click="creating=!creating"/><div class="ml-auto w-48"><FormControl v-model="search" placeholder="Search conversations" aria-label="Search conversations"/></div></div><div v-if="creating" class="toolbar"><DocumentForm v-model="newConversation" :fields="conversationFields"/><Button label="Create draft" :disabled="!contactData.find(c=>c.id===newContact)?.channels.includes(newChannel)" @click="createConversation"/><Button label="Cancel" @click="creating=false"/></div><div class="inbox-grid flex-1 min-h-0" :class="{'mobile-chat':mobileChat,'hide-details':!showDetails}"><section class="conversation-list"><PagedRows :fetch-page="conversationSource" :query="search" :revision="filter+selectedFolder+rows.map(t=>t.id).join('|')" :row-height="112" label="Conversations"><template #default="{item:t}"><button class="conversation-item w-full text-left" :class="{selected:active===t.id}" @click="openChat(t.id)"><div class="flex gap-2 items-center"><Avatar :label="t.name"/><strong class="text-base truncate">{{t.name}}</strong><span v-if="t.unread" class="ml-auto text-xs rounded bg-ink-gray-8 text-white px-1.5 py-0.5">{{t.unread}}</span><span v-else class="ml-auto text-xs text-ink-gray-4">{{t.time}}</span></div><p class="text-sm text-ink-gray-5 truncate my-2">{{t.messages.at(-1)?.text||'New conversation'}}</p><div class="flex justify-between"><Badge :label="t.channel"/><span class="text-xs text-ink-gray-5">{{t.team}}</span></div></button></template></PagedRows></section><section class="thread-panel"><div class="flex items-center gap-2 px-4 h-14 border-b shrink-0"><Button class="mobile-only" icon="arrow-left" label="Back to conversations" @click="mobileChat=false"/><strong class="text-base">{{current.name}}</strong><Badge :label="current.status"/><Button class="ml-auto" :label="current.status==='Open'?'Resolve':'Reopen'" @click="current.status=current.status==='Open'?'Resolved':'Open'"/><Button class="details-toggle" icon="sidebar" label="Show details" @click="showDetails=!showDetails"/></div><div class="channel-toolbar" aria-label="Filter messages by channel"><button v-for="ch in ['All',...availableChannels]" :key="ch" class="channel-tab" :class="{chosen:channelFilter===ch}" :aria-pressed="channelFilter===ch" @click="channelFilter=ch">{{ch==='All'?'All channels':ch}}</button></div><ConversationTimeline :conversation="active+':'+channelFilter" :messages="conversationMessages"/><div class="composer"><div class="flex items-center gap-2 px-3 pt-2"><Button label="Reply" :variant="note?'ghost':'subtle'" @click="note=false"/><Button label="Note" :variant="note?'subtle':'ghost'" @click="note=true"/><span v-if="note" class="ml-auto text-xs text-ink-gray-5">Internal</span><div v-else class="reply-channel ml-auto"><FormControl type="select" :model-value="replyChannel||current.channel" :options="availableChannels" @update:modelValue="replyChannel=$event"/></div></div><div class="p-3"><FormControl v-if="!note && workspaceItems.some(i=>i.view==='Canned replies'&&i.channels.includes(replyChannel||current.channel))" class="mb-3" type="select" label="Canned reply" :model-value="''" :options="[{label:'Select a reply',value:''},...workspaceItems.filter(i=>i.view==='Canned replies'&&i.channels.includes(replyChannel||current.channel)).map(i=>({label:i.title,value:i.id}))]" @update:modelValue="id=>{if(id)draft=workspaceItems.find(i=>i.id===id).message}"/><FormControl v-model="draft" type="textarea" :rows="2" :placeholder="note?'Write a note…':'Write a reply…'" aria-label="Message"/></div><div class="flex justify-end px-3 pb-3"><Button :label="note?'Add note':'Send'" variant="solid" :disabled="!draft.trim()" @click="send"/></div></div></section><aside class="details-panel" :class="{'details-open':showDetails}"><div class="flex items-center justify-between"><strong class="text-sm">Conversation</strong><Button class="details-toggle" icon="x" label="Close details" @click="showDetails=false"/></div><FormControl label="Team" type="select" :options="teams.filter(t=>t.channels.includes(current.channel)).map(t=>t.name)" v-model="current.team" @update:modelValue="current.assignee='Unassigned'"/><FormControl label="Assignee" type="select" :options="['Unassigned','You',...(teams.find(t=>t.name===current.team)?.members.map(m=>m.name)||[])]" v-model="current.assignee"/><div><div class="field-label mb-2">Handled by</div><div class="flex justify-between items-center"><span class="text-sm">{{current.bot?'Assistant':'Human'}}</span><Button :label="current.bot?'Take over':'Resume bot'" @click="current.bot=!current.bot;current.assignee=current.bot?'Unassigned':'You'"/></div></div><hr/><strong class="text-sm block">Contact</strong><Avatar :label="current.name" size="lg"/><div class="text-base">{{current.name}}</div><Badge :label="current.contact?'Linked':'Uncategorized'"/><hr/><FormControl label="Important" type="checkbox" v-model="current.important"/><div><div class="field-label">Folders</div><FormControl v-for="f in folders" :key="f.id" type="checkbox" :label="f.name" :model-value="f.threads.includes(active)" @update:modelValue="toggleFolder(f.id)" class="mb-2"/></div><div class="field-label">Channel</div><div class="text-sm">{{current.channel}}</div></aside></div></template>
<ConnectedMessages v-else-if="view==='Messages'"/><AutomationWorkspace v-else-if="view==='Automation'"/><WhatsAppWorkspace v-else-if="view==='WhatsApp'"/><div v-else-if="view==='Channels'" class="page-body"><div class="settings-layout"><nav class="settings-nav"><template v-for="ch in ['WhatsApp','Telegram','Email']" :key="ch"><button class="nav-item" @click="expandedChannel=expandedChannel===ch?'':ch;channelSettings=ch">{{ch}}</button><button v-if="expandedChannel===ch" class="nav-item pl-6" @click="channelSettings=ch">Settings</button></template></nav><section class="p-5 space-y-5"><h2 class="text-lg font-semibold">{{channelSettings||'Channels'}}</h2><template v-if="channelSettings"><Badge label="Not connected"/><FormControl label="Channel" :model-value="channelSettings" disabled/><FormControl label="Account" placeholder="Not configured" disabled/><p class="text-sm text-ink-gray-5">Configuration is managed by System Manager.</p></template></section></div></div><div v-else-if="view==='Teams'" class="page-body"><template v-if="!team"><div class="max-w-sm mb-4"><FormControl type="search" v-model="teamSearch" placeholder="Search teams" aria-label="Search teams"/></div><RelayTable :fetch-page="teamSource" :query="teamSearch" :revision="teams.length" :columns="[{key:'name',label:'Team'},{key:'members',label:'Members'},{key:'channels',label:'Channels',minWidth:200},{key:'actions',label:''}]" label="Teams"><template #members="{item}">{{item.members.length}}</template><template #channels="{item}"><Badge v-for="channel in item.channels" :key="channel" :label="channel" class="mr-1"/></template><template #actions="{item}"><Button :label="'Edit '+item.name" @click="edit(item)"/></template></RelayTable></template><div v-else class="form-page"><Button label="Teams" icon-left="arrow-left" variant="ghost" @click="team=null;error='';saved=''"/><h2 class="text-xl font-semibold">{{original||'New team'}}</h2><DocumentForm v-model="team" :fields="[{name:'name',label:'Team name',type:'Data',required:true},{name:'channels',label:'Channels',type:'MultiSelect',options:['WhatsApp','Email','Telegram'],required:true}]"/><section><h3 class="font-medium mb-3">Members</h3><div v-for="(m,i) in team.members" :key="m.name" class="flex items-center gap-3 mb-4"><Avatar :label="m.name"/><span class="text-base flex-1">{{m.name}}</span><FormControl type="select" :aria-label="'Role for '+m.name" :options="['Manager','Agent']" v-model="m.role"/><Button icon="x" :aria-label="'Remove '+m.name" @click="team.members.splice(i,1)"/></div><FormControl label="Add member" type="select" :model-value="''" :options="[{label:'Select a member',value:''},...['Sakthi','Priya N.','Ravi M.','Meera S.','Arun D.'].filter(n=>!team.members.some(m=>m.name===n))]" @update:modelValue="v=>{if(v)team.members.push({name:v,role:'Agent'})}"/></section><ErrorMessage :message="error"/></div></div>
<WorkspaceView v-else-if="['Dashboard','Contacts','Campaigns','Canned replies'].includes(view)" :key="view" :view="view" :threads="threads" :contacts="contactData" :items="workspaceItems" @open="openChat" @filter="setFilter"/><template v-else><div v-if="!flowOpen" class="page-body"><div class="max-w-sm mb-4"><FormControl v-model="flowSearch" type="search" placeholder="Search flows" aria-label="Search flows"/></div><RelayTable :fetch-page="flowSource" :query="flowSearch" :revision="String(published)" :columns="[{key:'name',label:'Name'},{key:'channels',label:'Channels',minWidth:200},{key:'trigger',label:'Trigger'},{key:'status',label:'Status'},{key:'actions',label:''}]" label="Flows"><template #channels="{item}"><Badge v-for="channel in item.channels" :key="channel" :label="channel" class="mr-1"/></template><template #status="{item}"><Badge :label="item.status"/></template><template #actions><Button label="Edit flow" @click="flowOpen=true"/></template></RelayTable></div><div v-else class="flow-layout flex-1 min-h-0"><div class="flow-canvas"><Button label="Flows" icon-left="arrow-left" @click="flowOpen=false"/><div class="flex flex-col items-center py-6"><template v-for="(n,i) in nodes" :key="n.id"><div v-if="i" class="flow-edge h-7"></div><button class="flow-node text-left" :class="{selected:selected===n.id}" @click="selected=n.id"><div class="flex gap-2 items-center text-xs text-ink-gray-5 mb-2"><FeatherIcon :name="n.icon" class="h-4 w-4"/>{{n.type}}</div><div class="text-base font-medium">{{n.label}}</div></button></template></div></div><aside class="flow-inspector space-y-5"><h2 class="text-base font-semibold">{{node.type}}</h2><FormControl label="Label" v-model="node.label" @update:modelValue="published=false;saved=''"/><FormControl :label="node.field" required :type="['Reply','Ask'].includes(node.type)?'textarea':'text'" v-model="node.value" @update:modelValue="published=false;saved=''"/><ErrorMessage :message="error"/></aside></div></template>
</main></div></template>
